with open('frontend/ticket-pages.mjs', 'r', encoding='utf-8') as f:
    content = f.read()

target = '<button class="btn" type="submit">Eskalasi Tiket</button></form></section>'
replacement = '''<button class="btn" type="submit">Eskalasi Tiket</button></form></section><section data-archive-ticket hidden class="vy-contact-form"><h2>Pengarsipan dan Pemulihan Tiket (M11)</h2><div data-archive-actions class="hd-actions" style="margin-bottom:1rem;"><button type="button" class="btn" data-btn-archive aria-haspopup="dialog" style="background:#6c757d;color:#fff;">Arsipkan Tiket</button><button type="button" class="btn" data-btn-restore-archive aria-haspopup="dialog" style="background:#198754;color:#fff;" hidden>Pulihkan dari Arsip</button></div><p data-archive-status role="status"></p><dialog data-archive-dialog class="piui-dialog" role="dialog" aria-modal="true" aria-labelledby="archive-dialog-title" style="max-width:500px;padding:1.5rem;border:1px solid #333;border-radius:8px;"><div class="piui-dialog__header" style="display:flex;justify-content:space-between;align-items:center;"><h3 id="archive-dialog-title">Konfirmasi Pengarsipan Tiket</h3><button type="button" class="piui-icon-btn" data-close-archive-dialog aria-label="Tutup dialog arsip">&times;</button></div><form data-form-archive style="margin-top:1rem;"><p>Tiket yang diarsipkan akan disimpan dalam repositori arsip. Riwayat, komentar, dan lampiran tetap dipertahankan.</p><div class="vy-input-group"><label for="archive-reason">Alasan pengarsipan</label><input class="vy-input" id="archive-reason" name="reason" type="text" placeholder="Uraikan alasan pengarsipan..." required></div><div class="hd-actions" style="margin-top:1rem;"><button type="submit" class="btn" style="background:#dc3545;color:#fff;">Konfirmasi Arsip</button><button type="button" class="btn" data-close-archive-dialog>Batal</button></div></form></dialog><dialog data-restore-dialog class="piui-dialog" role="dialog" aria-modal="true" aria-labelledby="restore-dialog-title" style="max-width:500px;padding:1.5rem;border:1px solid #333;border-radius:8px;"><div class="piui-dialog__header" style="display:flex;justify-content:space-between;align-items:center;"><h3 id="restore-dialog-title">Konfirmasi Pemulihan Arsip Tiket</h3><button type="button" class="piui-icon-btn" data-close-restore-dialog aria-label="Tutup dialog pemulihan">&times;</button></div><form data-form-restore-archive style="margin-top:1rem;"><p>Tiket ini akan dipulihkan dari status arsip kembali ke status operasional aktif.</p><div class="vy-input-group"><label for="restore-reason">Alasan pemulihan arsip</label><input class="vy-input" id="restore-reason" name="reason" type="text" placeholder="Uraikan alasan pemulihan..." required></div><div class="hd-actions" style="margin-top:1rem;"><button type="submit" class="btn" style="background:#198754;color:#fff;">Konfirmasi Pemulihan</button><button type="button" class="btn" data-close-restore-dialog>Batal</button></div></form></dialog></section>'''

assert target in content, 'target not found in frontend/ticket-pages.mjs'
new_content = content.replace(target, replacement, 1)
with open('frontend/ticket-pages.mjs', 'w', encoding='utf-8') as f:
    f.write(new_content)
print('Updated frontend/ticket-pages.mjs successfully')
